def load_v45_macro_data():
    obj=json.loads(zlib.decompress(base64.b85decode(_DATA)))
    routes={int(k):v for k,v in obj['routes'].items()}
    new={tuple(k):v for k,v in obj['new']}
    old={tuple(k):v for k,v in obj['old']}
    return routes,new,old
